mapper.select:
SELECT f.flow_id, f.merchant_base_id, f.order_main_id, f.flow_type, f.flow_amount, f.goods_amount, f.balance_after, f.description, f.create_time, -- 订单详情 o.order_no, o.user_nickname, o.order_type, o.order_status, o.pay_amount, o.delivery_fee_amount, o.pay_time, o.complete_time, -- 商品明细（仅外卖订单） GROUP_CONCAT(CONCAT(d.goods_name, ' x', d.quantity) SEPARATOR ', ') AS goods_detail FROM merchant_wallet_flow f LEFT JOIN order_main o ON f.order_main_id = o.order_main_id LEFT JOIN order_takeout_detail d ON o.order_main_id = d.order_main_id AND o.order_type = 1 WHERE f.merchant_base_id = #{merchantBaseId}
AND f.flow_type = #{flowType}
AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND f.create_time >= #{startTime}
AND f.create_time <= #{endTime}
GROUP BY f.flow_id ORDER BY f.create_time DESC

SELECT * FROM merchant_wallet_flow

    AND merchant_base_id = #{merchantBaseId}
    AND flow_type = #{flowType}

ORDER BY create_time DESC

